"""tray_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 1 extrusion(s) and 23 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python tray_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along y
z1 = 3.175    # level along y
hole_d1 = 2.2
hole_d2 = 3.2
hole_d3 = 3.8
hole_d4 = 5.0
hole_d5 = 6.5
hole_d6 = 9.2

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y 0.0 to 3.175 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(355.6, -265.0561), P(355.6, -89.9009)),
    cf.segment(P(355.6, -89.9009), P(354.9208, -88.2379)),
    cf.segment(P(354.9208, -88.2379), P(268.0065, -1.2461)),
    Edge.makeThreePointArc(P(268.0065, -1.2461), P(266.2814, -0.1978), P(265.0, 0.0)),
    cf.segment(P(265.0, 0.0), P(90.6, 0.0)),
    Edge.makeThreePointArc(P(90.6, 0.0), P(88.7402, -0.4285), P(87.5934, -1.2462)),
    cf.segment(P(87.5934, -1.2462), P(0.6762, -88.2453)),
    cf.segment(P(0.6762, -88.2453), P(0.0, -89.9009)),
    cf.segment(P(0.0, -89.9009), P(0.0, -265.699)),
    cf.segment(P(0.0, -265.699), P(0.6809, -267.3662)),
    cf.segment(P(0.6809, -267.3662), P(87.5935, -354.3539)),
    Edge.makeThreePointArc(P(87.5935, -354.3539), P(89.3186, -355.4022), P(90.6, -355.6)),
    cf.segment(P(90.6, -355.6), P(265.0, -355.6)),
    Edge.makeThreePointArc(P(265.0, -355.6), P(266.8598, -355.1715), P(268.0066, -354.3538)),
    cf.segment(P(268.0066, -354.3538), P(354.9248, -267.3523)),
    cf.segment(P(354.9248, -267.3523), P(355.5373, -265.8527)),
    cf.segment(P(355.5373, -265.8527), P(355.6, -265.0561)),
)
part = prism(outline_1, z0, z1)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (330.25, -177.75, hole_d5, z0, z1),
    (101.6, -309.75, hole_d5, z0, z1),
    (101.6, -45.8, hole_d5, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- 2. cut: y 0.0 to 3.175 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(171.4475, -189.0268), P(171.4652, -157.8378)),
    Edge.makeThreePointArc(P(171.4652, -157.8378), P(172.3573, -156.1693), P(173.99, -155.5745)),
    cf.segment(P(173.99, -155.5745), P(181.9287, -155.5951)),
    Edge.makeThreePointArc(P(181.9287, -155.5951), P(183.5558, -156.4823), P(184.1522, -158.115)),
    cf.segment(P(184.1522, -158.115), P(184.1354, -197.7414)),
    Edge.makeThreePointArc(P(184.1354, -197.7414), P(183.3735, -199.3114), P(181.7722, -200.0265)),
    cf.segment(P(181.7722, -200.0265), P(173.4943, -200.0044)),
    Edge.makeThreePointArc(P(173.4943, -200.0044), P(172.0297, -199.1168), P(171.45, -197.4908)),
    cf.segment(P(171.45, -197.4908), P(171.4475, -189.0268)),
)
part = part - prism(outline_2, z0, z1)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (198.1, -198.1, hole_d1, z0, z1),
    (198.1, -157.5, hole_d1, z0, z1),
    (157.5, -157.5, hole_d1, z0, z1),
    (157.5, -198.1, hole_d1, z0, z1),
    (266.75, -177.75, hole_d3, z0, z1),
    (133.4, -254.75, hole_d3, z0, z1),
    (133.4, -100.75, hole_d3, z0, z1),
    (295.25, -60.3, hole_d6, z0, z1),
    (60.3, -60.3, hole_d6, z0, z1),
    (295.25, -295.25, hole_d6, z0, z1),
    (60.3, -295.25, hole_d6, z0, z1),
    (101.6, -15.9, hole_d2, z0, z1),
    (254.0, -15.9, hole_d2, z0, z1),
    (101.6, -339.75, hole_d2, z0, z1),
    (254.0, -339.75, hole_d2, z0, z1),
    (279.4, -279.4, hole_d4, z0, z1),
    (76.25, -279.4, hole_d4, z0, z1),
    (279.4, -76.25, hole_d4, z0, z1),
    (76.25, -76.25, hole_d4, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "tray_exact.step")
